#include "postquantiquecoin/blockchain/Block.h"
#include "postquantiquecoin/blockchain/MerkleTree.h"
#include "postquantiquecoin/core/Constants.h"
#include "postquantiquecoin/core/Serialization.h"
namespace pqc { std::string Block::GetHash() const { return header.GetHash(); } std::vector<uint8_t> Block::Serialize() const { Serializer s; auto hs=header.Serialize(); s.Bytes(hs); s.U64(transactions.size()); for(const auto& tx:transactions) s.Bytes(tx.Serialize(true)); return s.Data(); } Result<Block> Block::Deserialize(const std::vector<uint8_t>&){ return Result<Block>::Err("block deserialization is unavailable for this binary format version"); } Result<void> Block::ValidateBasic() const { if(transactions.empty()) return Result<void>::Err("block without transactions"); if(Serialize().size()>constants::MAX_BLOCK_BYTES) return Result<void>::Err("block too large"); if(!transactions[0].IsCoinbase()) return Result<void>::Err("first transaction is not coinbase"); for(size_t i=1;i<transactions.size();++i) if(transactions[i].IsCoinbase()) return Result<void>::Err("extra coinbase"); for(const auto& tx:transactions){ auto r=tx.ValidateBasic(); if(r.IsErr() && !tx.IsCoinbase()) return r; } if(header.merkleRoot!=MerkleTree::ComputeRoot(transactions)) return Result<void>::Err("bad merkle root"); return Result<void>::Ok(); } }
